const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Lake Kariba boundaries (approximate center and region)
  const lakeKariba = ee.Geometry.Rectangle([25.5, -18.5, 29.0, -15.5]);

  // Define time periods: December 2018 and December 2019
  const dec2018Start = '2018-12-01';
  const dec2018End = '2018-12-31';
  const dec2019Start = '2019-12-01';
  const dec2019End = '2019-12-31';

  // Function to calculate NDWI and filter for valid pixels
  function processDecember(startDate, endDate) {
    return ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
      .filterBounds(lakeKariba)
      .filterDate(startDate, endDate)
      .map(function(img) {
        // Cloud masking using QA_PIXEL
        const qaMask = img.select('QA_PIXEL').bitwiseAnd(32).eq(0);
        // Select bands: B5 (NIR), B4 (Red)
        const nir = img.select('SR_B5');
        const red = img.select('SR_B4');
        // Calculate NDWI: (NIR - Red) / (NIR + Red)
        const ndwi = nir.subtract(red).divide(nir.add(red)).rename('NDWI');
        return ndwi.updateMask(qaMask);
      });
  }

  // Retrieve collections
  const col2018 = processDecember(dec2018Start, dec2018End);
  const col2019 = processDecember(dec2019Start, dec2019End);

  const size2018 = col2018.size().getInfo();
  const size2019 = col2019.size().getInfo();

  console.log(`Dec 2018 Images: ${size2018}`);
  console.log(`Dec 2019 Images: ${size2019}`);

  // Check for empty collections
  if (size2018 === 0 || size2019 === 0) {
    console.log('No images found for one or both December periods.');
    console.log('C1');
    return;
  }

  // Merge images and calculate median NDWI
  const median2018 = col2018.median();
  const median2019 = col2019.median();

  // Check pixel counts (valid pixels after masking)
  const count2018 = median2018.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: lakeKariba,
    scale: 30,
    maxPixels: 1e9
  }).get('NDWI').getInfo();

  const count2019 = median2019.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: lakeKariba,
    scale: 30,
    maxPixels: 1e9
  }).get('NDWI').getInfo();

  console.log(`Dec 2018 Valid Pixels: ${count2018}`);
  console.log(`Dec 2019 Valid Pixels: ${count2019}`);

  if (count2018 === 0 || count2019 === 0) {
    console.log('No valid pixels after cloud masking.');
    console.log('C2');
    return;
  }

  // Calculate mean NDWI for water bodies (proxy for water level)
  const mean2018 = median2018.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: lakeKariba,
    scale: 30,
    maxPixels: 1e9
  }).get('NDWI').getInfo();

  const mean2019 = median2019.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: lakeKariba,
    scale: 30,
    maxPixels: 1e9
  }).get('NDWI').getInfo();

  console.log(`Dec 2018 Mean NDWI: ${(mean2018 || 0).toFixed(4)}`);
  console.log(`Dec 2019 Mean NDWI: ${(mean2019 || 0).toFixed(4)}`);

  // Validation: check for NaN or invalid results
  if (mean2018 === null || mean2018 === undefined || isNaN(mean2018) ||
      mean2019 === null || mean2019 === undefined || isNaN(mean2019)) {
    console.log('Calculation returned invalid values.');
    console.log('C3');
    return;
  }

  // Compare water levels
  if (mean2019 > mean2018) {
    console.log('Water levels (NDWI) higher in Dec 2019 than Dec 2018.');
    console.log('A');
  } else {
    console.log('Water levels (NDWI) not higher in Dec 2019 than Dec 2018.');
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
